/*
 * A085936  Numbers k such that the number resulting from sorting the digits
 *          of k in ascending order + the sum of the squares of the digits of
 *          k is a palindrome. Or, sortdigits(k) + digitsumsquare(k) is a
 *          palindrome.
 * https://oeis.org/A085936
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   a(n) is the nth positive integer k such that sortdigits(k) +
 *            digit_square_sum(sortdigits(k)) is a palindrome. The sequence is
 *            generated by scanning successive integers
 * Range:     u8 n <= 38, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* The code works for both C and C++ (builds that use arbitrary‑precision
   seq_t).  All heavy work is done on uint64_t, which is enough for the
   required range of n (up to at least 10 000).  The result is
   cast to seq_t before returning. */

#include <stdbool.h>
#include <stdint.h>
#include <stdlib.h>

/* Compute the integer obtained by sorting the decimal digits of n in ascending order. */
static uint64_t sort_digits(uint64_t n) {
    unsigned cnt[10] = {0};
    if (n == 0) {      /* keep the zero digit */
        cnt[0] = 1;
    } else {
        while (n > 0) {
            cnt[n % 10]++;
            n /= 10;
        }
    }
    uint64_t res = 0;
    for (int d = 0; d <= 9; ++d) {
        while (cnt[d]--) {
            res = res * 10 + d;
        }
    }
    return res;
}

/* Sum of squares of decimal digits of n. */
static uint64_t digit_square_sum(uint64_t n) {
    uint64_t sum = 0;
    if (n == 0) {      /* handle 0 specially */
        return 0;
    }
    while (n > 0) {
        unsigned d = n % 10;
        sum += d * d;
        n /= 10;
    }
    return sum;
}

/* Check whether x is a decimal palindrome. */
static bool is_palindrome(uint64_t x) {
    uint64_t rev = 0, orig = x;
    while (x > 0) {
        rev = rev * 10 + (x % 10);
        x /= 10;
    }
    return rev == orig;
}

/* Determine whether k satisfies the property. */
static bool good_k(uint64_t k) {
    uint64_t sorted = sort_digits(k);
    uint64_t sumsq  = digit_square_sum(sorted);
    uint64_t total  = sorted + sumsq;
    return is_palindrome(total);
}

/* Main sequence function. */
seq_t a(idx_t n) {
    if (n < 1) return (seq_t)0;   /* offset is 1 */

    /* Static storage for generated terms. */
    static uint64_t *terms = NULL;
    static size_t term_len = 0;
    static size_t term_cap = 0;

    /* Keep track of the next integer to test. */
    static uint64_t next_k = 1;

    /* Grow the table and generate terms until we have at least n. */
    while (term_len < (size_t)n) {
        if (good_k(next_k)) {
            /* Add to the table. */
            if (term_len == term_cap) {
                size_t new_cap = (term_cap == 0) ? 16 : term_cap * 2;
                uint64_t *tmp = (uint64_t *)realloc(terms, new_cap * sizeof(uint64_t));
                if (!tmp) { /* allocation failure – return 0 */
                    free(terms);
                    terms = NULL;
                    term_cap = term_len = 0;
                    return (seq_t)0;
                }
                terms = tmp;
                term_cap = new_cap;
            }
            terms[term_len++] = next_k;
        }
        ++next_k;
    }

    return (seq_t)terms[n - 1];
}
